//! check the string extraction and filters against Python FLOSS.
//! the fixtures in `tests/data` were generated by running FLOSS's
//! `floss.utils.strip_string` and `floss.strings.extract_ascii_unicode_strings`.
use floss::strings::{extract_ascii_utf16, strip_string, Encoding};

#[test]
fn strip_string_matches_floss() {
    let cases: Vec<(String, String)> =
        serde_json::from_str(include_str!("data/strip_string.json")).unwrap();
    let mut failures = vec![];
    for (input, expected) in cases.iter() {
        let found = strip_string(input);
        if &found != expected {
            failures.push(format!("{input:?}: expected {expected:?}, found {found:?}"));
        }
    }
    assert!(failures.is_empty(), "{} of {} differ:\n{}", failures.len(), cases.len(), failures.join("\n"));
}

#[test]
fn extract_strings_matches_floss() {
    let cases: Vec<(String, Vec<(String, usize, String)>)> =
        serde_json::from_str(include_str!("data/extract_strings.json")).unwrap();
    for (hex, expected) in cases.iter() {
        let buf: Vec<u8> = (0..hex.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
            .collect();
        let found: Vec<(String, usize, String)> = extract_ascii_utf16(&buf)
            .into_iter()
            .map(|s| {
                let encoding = match s.encoding {
                    Encoding::Ascii => "ASCII",
                    Encoding::Utf16Le => "UTF-16LE",
                };
                (s.string, s.offset, encoding.to_string())
            })
            .collect();
        assert_eq!(&found, expected, "buffer: {hex}");
    }
}
